u16 stage_terrain_at(u8 map, s16 tileX, s16 tileY)
{
    if (map >= STAGE0_MAP_COUNT) return TERRAIN_SOLID;
    if (tileX < 0 || tileX >= STAGE0_MAP_W) return TERRAIN_SOLID;
    if (tileY < 0 || tileY >= STAGE0_MAP_H) return TERRAIN_UNBLOCKED;
    return stage0_terrain[map][tileY * STAGE0_MAP_W + tileX];
}
